cpp.setup:
auto* trigger = new fluent::basicinput::Button(QStringLiteral("Show Dialog"), %PARENT%);
trigger->setFluentStyle(fluent::basicinput::Button::Accent);
trigger->setFixedSize(140, 32);
trigger->move(130, 109);
trigger->show();
auto* control = new fluent::dialogs_flyouts::Dialog(%PARENT%);
control->setAnimationEnabled(false);
auto* layout = new QVBoxLayout(control);
layout->setContentsMargins(24, 20, 24, 20);
layout->setSpacing(8);
auto* title = new fluent::textfields::Label(QStringLiteral("Export archive"), control);
title->setFluentTypography(Typography::FontRole::Subtitle);
layout->addWidget(title);
auto* body = new fluent::textfields::Label(QStringLiteral("Include build metadata and theme assets in the exported package."), control);
body->setWordWrap(true);
body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(body);
layout->addStretch(1);
auto* actions = new QHBoxLayout;
actions->setSpacing(8);
actions->addStretch(1);
auto* cancelButton = new fluent::basicinput::Button(QStringLiteral("Cancel"), control);
cancelButton->setMinimumWidth(84);
auto* confirmButton = new fluent::basicinput::Button(QStringLiteral("Export"), control);
confirmButton->setFluentStyle(fluent::basicinput::Button::Accent);
confirmButton->setMinimumWidth(84);
actions->addWidget(cancelButton);
actions->addWidget(confirmButton);
layout->addLayout(actions);
control->resize(316, 174);
QObject::connect(cancelButton, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Dialog::reject);
QObject::connect(confirmButton, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Dialog::accept);
QObject::connect(trigger, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Dialog::open);
control->open();
